export type BlockId =
  | "keyPartners"
  | "keyActivities"
  | "keyResources"
  | "valueProps"
  | "relationships"
  | "channels"
  | "segments"
  | "costs"
  | "revenue";

export type ItemStatus = "hypothesis" | "validated" | "invalidated";

export interface CanvasItem {
  id: string;
  text: string;
  status: ItemStatus;
  /** "suggested" = generated by the co-pilot rather than stated by the founder */
  source?: "suggested";
}

export type Canvas = Record<BlockId, CanvasItem[]>;

export interface CanvasVersion {
  id: string;
  label: string;
  note: string;
  createdAt: string;
  canvas: Canvas;
}

export interface TestCard {
  id: string;
  title: string;
  block: BlockId;
  hypothesis: string;
  experiment: string;
  metric: string;
  criteria: string;
}

export interface ChatMessage {
  id: string;
  role: "coach" | "user";
  text: string;
  flags?: string[];
}

export type Stage = 1 | 2 | 3 | 4 | 5;

